import{z as B,x as d,o as t,c as p,q as s,j as o,D as n,d as l,s as r,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"LIS 与 LCS","description":"","frontmatter":{"title":"LIS 与 LCS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lis-lcs.md","filePath":"cs/lis-lcs.md","lastUpdated":1791063341000}'),A={name:"cs/lis-lcs.md"};function S(c,a,C,m,L,h){const i=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="lis-与-lcs" tabindex="-1">LIS 与 LCS <a class="header-anchor" href="#lis-与-lcs" aria-label="Permalink to &quot;LIS 与 LCS&quot;">​</a></h1><div class="epigraph"><p>最长上升子序列 $O(n\\log n)$ 维护最小尾；最长公共子序列 $O(nm)$ 格图，可滚动数组。</p><footer>—— 据 Fredman, On Computing the Length of Longest Increasing Subsequences, 1975；CLRS 第 15.4 节整理</footer></div><p>上一课<a href="/cs/rerooting-dp">换根 DP</a>在树上做无根化，现在回到数组上的序列。主干的区间 DP 课已警告过：LCS 不是区间切点问题。本课的缺口是两张表——LIS 的耐心排序与最小尾，LCS 的二维格；树 DP 不再重写。下一课编辑距离是 LCS 的近亲，先把格子在这里铺好。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LIS 求严格上升（或非降）的最长子序列。逐元素转移 \\(dp[i]=\\max_{j\\lt i,a_j\\lt a_i} dp[j]+1\\) 是 \\(O(n^2)\\)：每个点回头看所有前驱。换一个状态才降得下去：维护数组 <code>tail[len]</code>，记录「长度为 len 的上升子序列目前见过的最小结尾」。同长度下结尾越小，后面能接上的元素越多，拿最小尾作代表不会更差。<code>tail</code> 随扫描保持递增，每来一个元素二分定位、替换或追加，\\(O(n\\log n)\\)。Dilworth 定理从反面对照：LIS 的长度等于把序列划分成最少不升链的数目，本课点名不证明。</p><p>LCS 建在两串 \\(A,B\\) 的前缀对上：\\(dp[i][j]\\) 表示各自前缀的答案，末位不等时两者至少有一个用不上，取左、上较大者；相等才由对角 \\(+1\\)。\\(\\Theta(nm)\\) 个格子一个不省。公共子串要求连续，不等时归零，是另一套转移。缺口是这两张表，不是编辑距离（下一课）。</p><h3 id="lis-不是子数组" tabindex="-1">LIS 不是子数组 <a class="header-anchor" href="#lis-不是子数组" aria-label="Permalink to &quot;LIS 不是子数组&quot;">​</a></h3><p>子序列允许跳过元素，与要求连续的上升子数组是两道题：后者一次扫描或差分就够。别拿单调队列硬套 LIS——它维护的是滑动窗口最值，状态含义不同。</p><p><span class="marginnote">直觉类比：<code>tail</code> 像各长度组的「最小尾纪录榜」——同长度里结尾越小，后面越容易有元素接上。新元素要么刷新某一组的纪录（替换），要么开创更长的一组（追加），榜单始终只记每组最好的那个。</span></p><p><span class="marginnote">Fredman 1975。CLRS 15.4 LCS。Hunt–Szymanski 结合相等对。后课 Hirschberg 线性空间 LCS/编辑距离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LIS 扫一遍：每个元素在 <code>tail</code> 里二分找位置，替换则更新某长度的最小尾，越界则总长加一；求方案需另记 <code>id</code> 与前驱，结束时从最长处回跳。二分对严格上升取第一个 \\(\\ge x\\) 的尾，非降则改成第一个 \\(\\gt x\\)。LCS 按行填二维表；只要长度时用滚动数组把空间压到 \\(O(\\min(n,m))\\)。</p>',12)),(t(),o(E,null,{default:n(()=>[r(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%BA%8F%E5%88%97%20a%22%5D%20--%3E%20TAIL%5B%22tail%5Blen%5D%20%E6%9C%80%E5%B0%8F%E7%BB%93%E5%B0%BE%22%5D%0A%20%20AB%5B%22%E4%B8%A4%E4%B8%B2%22%5D%20--%3E%20GRID%5B%22dp%5Bi%5D%5Bj%5D%20%E6%A0%BC%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"相等元素按上一段的口径处理，二分方向决定严格与否。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},[l("数字实例：扫 \\([3, 1, 4, 1, 5]\\)："),e("code",null,"tail"),l(" 依次为 \\([3]\\) → \\([1]\\) → \\([1,4]\\) → \\([1,4]\\)（第二个 1 替换首位）→ \\([1,4,5]\\)，最终长度 3，对应 LIS \\(1,4,5\\)。全程每元素只做一次二分加一次写。")])],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[e("code",null,"tail"),l(" 的不变量是同长度存最小结尾：任何同长度的可行结尾都可以在不缩短的前提下换成它，长度答案因此不失真；长度越大结尾越大这条单调性让二分合法。LCS 的最优子结构落点在前缀对：末位的取舍只牵动最后一行一列，子问题互不纠缠。对照状压：排列求 LIS 若用 bitmask 记「用过哪些元素」要 \\(2^n\\)，而 "),e("code",null,"tail"),l(" 只依赖值的大小次序，\\(O(n\\log n)\\) 就够；它与生成函数无关，别往计数上想。")],-1)),(t(),o(E,null,{default:n(()=>[r(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%AF%BB%E5%85%A5%E5%85%83%E7%B4%A0%20x%22%5D%20--%3E%20BS%5B%22%E5%9C%A8%20tail%20%E9%87%8C%E4%BA%8C%E5%88%86%E6%89%BE%E7%AC%AC%E4%B8%80%E4%B8%AA%20%E2%89%A5%20x%20%E7%9A%84%E5%B0%BE%22%5D%0A%20%20BS%20--%3E%7C%22%E6%89%BE%E5%88%B0%22%7C%20REP%5B%22%E6%9B%BF%E6%8D%A2%E8%AF%A5%E4%BD%8D%E7%BD%AE%EF%BC%9A%E5%90%8C%E9%95%BF%E5%BA%A6%E6%8D%A2%E6%9B%B4%E5%B0%8F%E5%B0%BE%22%5D%0A%20%20BS%20--%3E%7C%22%E9%83%BD%E6%9B%B4%E5%B0%8F%22%7C%20APP%5B%22%E8%BF%BD%E5%8A%A0%E5%88%B0%E6%9C%AB%E5%B0%BE%EF%BC%9A%E6%80%BB%E9%95%BF%E5%8A%A0%E4%B8%80%22%5D%0A%20%20REP%20--%3E%20INV%5B%22tail%20%E4%BB%8D%E4%BF%9D%E6%8C%81%E9%80%92%E5%A2%9E%EF%BC%8C%E4%BA%8C%E5%88%86%E7%BB%A7%E7%BB%AD%E5%90%88%E6%B3%95%22%5D%0A%20%20APP%20--%3E%20INV%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维及以上的多串 LCS——格子数连乘，规模立刻爆炸；也不写近似 LCS。后课默认：LIS \\(O(n\\log n)\\)；LCS \\(O(nm)\\)，引用时不再推导。下一课编辑距离与 Hirschberg。</p><p><span class="marginnote">常见误区：以为 LCS 的对角线顺出来就是最长公共子串。子序列允许跳字符，不等时取左、上较大者继续走；子串要求连续，不等必须归零重来——两套转移，答案可以差很远。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LIS：最小尾 + 二分 \\(O(n\\log n)\\)。</li><li>LCS：前缀对 \\(O(nm)\\)。</li><li>子序列可跳，不是子数组。</li><li>出处：Fredman, 1975；CLRS 第 15.4 节。</li></ul>',5))])}const f=B(A,[["render",S]]);export{D as __pageData,f as default};
